CREATE TABLE vendor_circuit_outcomes(run_id TEXT NOT NULL,fingerprint TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('confidence','reader','recovery')),vendor TEXT NOT NULL CHECK(vendor IN('confidence','reader')),exhausted INTEGER NOT NULL CHECK(exhausted IN(0,1)),operation_token TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL,failures_after INTEGER NOT NULL CHECK(typeof(failures_after)='integer' AND failures_after BETWEEN 0 AND 9007199254740991),PRIMARY KEY(run_id,fingerprint,role),FOREIGN KEY(run_id,fingerprint) REFERENCES documents(run_id,fingerprint),CHECK((role='confidence' AND vendor='confidence') OR (role IN('reader','recovery') AND vendor='reader')));
CREATE TRIGGER vendor_circuit_outcomes_immutable_update BEFORE UPDATE ON vendor_circuit_outcomes BEGIN SELECT RAISE(ABORT,'Vendor circuit outcomes are immutable'); END;
CREATE TRIGGER vendor_circuit_outcomes_immutable_delete BEFORE DELETE ON vendor_circuit_outcomes BEGIN SELECT RAISE(ABORT,'Vendor circuit outcome history is immutable'); END;
